/* ============================================
   SPLIT BUTTON COMPONENT
   Primary action + attached menu of alternatives
   ============================================ */

@layer rift.tokens, rift.preset, rift.components;

@layer rift.components {

.ds-split-button {
  display: inline-flex;
  align-items: stretch;
  /* On the filled variant the hairline of page showing between the
     segments is the split: a gap the width of the system hairline,
     not a drawn border. */
  gap: var(--border-025);
}

/* ============================================
   SEGMENT GEOMETRY
   Outer silhouette stays the Button pill; the
   meeting edges square off. The main segment's
   inner-edge padding tightens one step - the
   squared edge has no pill cap to clear, so
   the resting 16px reads as a hole before the
   chevron.
   ============================================ */

.ds-split-button .ds-split-button__main {
  border-start-end-radius: var(--radius-050);
  border-end-end-radius: var(--radius-050);
  padding-inline-end: var(--padding-300);
}

.ds-split-button .ds-split-button__main.ds-button--compact {
  padding-inline-end: var(--padding-200);
}

.ds-split-button .ds-split-button__trigger {
  border-start-start-radius: var(--radius-050);
  border-end-start-radius: var(--radius-050);
  /* Standalone, IconButton is a fixed even box; inside the split its
     explicit height would block the wrapper's align-items: stretch, and
     the main segment's height moves (secondary's border adds to it, a
     loading spinner grows it) — so the flat edges overhang at the seam.
     Let the flex stretch size it to the main segment instead. */
  height: auto;
  align-self: stretch;
  /* Icon side padding, as Button's: the chevron's cap side takes one step
     less than the even box would give it, so the trigger is a padding
     step narrower than the row height and the chevron sits centred in it,
     6px either side. This replaces the old optical nudge toward the seam,
     which reached the same seam-side gap by moving the glyph instead of
     trimming the cap. The compact trigger keeps its even box: its
     chevron already sits 6px from either side, and trimming it would put
     the glyph in the cap's curve. */
  width: calc(var(--control-height-default) - var(--padding-100));
}

.ds-split-button .ds-split-button__trigger.ds-icon-button--compact {
  width: var(--control-height-compact);
}

/* ============================================
   LOADING
   The trigger is inert while the main segment
   runs its async action, but it is busy, not
   broken: Button and IconButton both define
   loading as full-colour appearance with a
   progress cursor, and the disabled dim on one
   half would split the pill into two unrelated
   controls. When the main segment is disabled
   as well, the whole control dims together and
   this rule deliberately stands down.
   ============================================ */

.ds-split-button:has(.ds-button--loading:not(.ds-button--disabled)) .ds-split-button__trigger.ds-icon-button--disabled {
  opacity: 1;
  cursor: progress;
}

/* ============================================
   SECONDARY
   Both segments are outlined, so the gap would
   put two hairlines side by side at the seam.
   Collapse it: no gap, the trigger drops its
   leading border, and the main segment's own
   border is the one divider line.
   ============================================ */

.ds-split-button--secondary {
  gap: 0;
}

.ds-split-button--secondary .ds-split-button__trigger {
  border-inline-start: none;
}

} /* @layer rift.components */

import React from 'react';
import { Button } from '../Button/Button';
import { IconButton } from '../IconButton/IconButton';
import { DropdownMenu, type DropdownMenuEntry } from '../DropdownMenu/DropdownMenu';
import './SplitButton.css';
import '../../behaviors/direction.css';

export type { DropdownMenuEntry as SplitButtonMenuEntry } from '../DropdownMenu/DropdownMenu';

/** Props owned by SplitButton itself — everything else falls through to the primary button. */
type SplitButtonOwnProps = {
  /** Label of the primary action */
  label: string;
  /** Click handler for the primary action */
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  /** Menu entries for the alternative actions */
  items: DropdownMenuEntry[];
  /**
   * Emphasis, shared by both segments: `primary` (filled) or `secondary`
   * (outlined). The colour is `tone`'s job. `neutral` is the legacy value
   * from before the split and renders as `variant="primary" tone="neutral"`.
   */
  variant?: 'primary' | 'secondary' | 'neutral';
  /**
   * Colour, shared by both segments: `default` carries the action colour,
   * `neutral` the greys, `destructive` the danger colour.
   */
  tone?: 'default' | 'neutral' | 'destructive';
  /** Component size */
  size?: 'default' | 'compact';
  /** Disables both segments */
  disabled?: boolean;
  /** Shows a spinner on the primary segment and blocks interaction while an async action runs */
  loading?: boolean;
  /** Icon for the primary segment — Material Symbol name or custom element */
  iconLeft?: string | React.ReactNode;
  /** Horizontal alignment of the menu panel relative to the control */
  align?: 'start' | 'end';
  /** Accessible name of the menu trigger segment */
  menuLabel?: string;
  /** Additional CSS classes, applied to the wrapper around both segments, not the primary button */
  className?: string;
};

export interface SplitButtonProps
  extends SplitButtonOwnProps,
    Omit<React.ComponentPropsWithoutRef<'button'>, keyof SplitButtonOwnProps | 'type'> {}

/**
 * A primary action with an attached menu of alternatives — "Save" beside
 * "Save as draft" and "Save as template". One pill silhouette, two segments:
 * the label fires `onClick` directly, the chevron opens a DropdownMenu, so
 * the default stays one click away while the variants stay discoverable.
 *
 * Forwards a ref to the primary segment's button and spreads unrecognised
 * props onto that segment — while `className` composes onto the wrapper
 * around both segments. Menu behaviour (keyboard, outside click, sub-menus)
 * is DropdownMenu's, unchanged. Purely compositional (no 'use client'), like
 * ButtonGroup: the interactivity lives in the pieces it assembles.
 */
export const SplitButton = React.forwardRef<HTMLButtonElement, SplitButtonProps>(
  (
    {
      label,
      onClick,
      items,
      variant = 'primary',
      tone,
      size = 'default',
      disabled = false,
      loading = false,
      iconLeft,
      align = 'end',
      menuLabel = 'More actions',
      className = '',
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-split-button';

    // The legacy `neutral` variant is primary emphasis in the neutral tone.
    const emphasis = variant === 'neutral' ? 'primary' : variant;
    const resolvedTone = tone ?? (variant === 'neutral' ? 'neutral' : 'default');

    const classes = [
      baseClass,
      `${baseClass}--${emphasis}`,
      `${baseClass}--tone-${resolvedTone}`,
      className,
    ]
      .filter(Boolean)
      .join(' ');

    return (
      <span className={classes}>
        <Button
          {...rest}
          ref={ref}
          className={`${baseClass}__main`}
          label={label}
          iconLeft={iconLeft}
          variant={emphasis}
          tone={resolvedTone}
          size={size}
          disabled={disabled}
          loading={loading}
          onClick={onClick}
        />
        <DropdownMenu
          className={`${baseClass}__menu`}
          align={align}
          size={size}
          items={items}
          trigger={
            <IconButton
              className={`${baseClass}__trigger`}
              icon="keyboard_arrow_down"
              /* No self-labelling tooltip: the trigger must stay a direct flex
                 child of the split so align-self: stretch can size it to the
                 main segment — the tooltip wrapper would sit between them. */
              tooltip={false}
              label={menuLabel}
              variant={emphasis}
              tone={resolvedTone}
              size={size}
              disabled={disabled || loading}
            />
          }
        />
      </span>
    );
  },
);

SplitButton.displayName = 'SplitButton';
